import { access, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const checkOnly = process.argv.includes('--check');
const markerName = '.generated-by-sync-ai-config';
const markerContent =
  'Generated by scripts/sync-ai-config.mjs. Do not edit this directory manually.\n';

const managedOutputs = [
  path.join(root, '.agents', 'skills'),
  path.join(root, '.agents', 'rules'),
  path.join(root, '.codex', 'agents'),
];

function relative(filePath) {
  return path.relative(root, filePath).replaceAll(path.sep, '/');
}

async function exists(filePath) {
  try {
    await access(filePath);
    return true;
  } catch {
    return false;
  }
}

async function walkFiles(directory) {
  if (!(await exists(directory))) return [];
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];

  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const entryPath = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...(await walkFiles(entryPath)));
    if (entry.isFile()) files.push(entryPath);
  }

  return files;
}

function parseFrontmatter(source) {
  const normalized = source.replaceAll('\r\n', '\n');
  if (!normalized.startsWith('---\n')) return { attributes: {}, body: normalized.trim() };

  const closing = normalized.indexOf('\n---\n', 4);
  if (closing === -1) throw new Error('Frontmatter không có dấu đóng ---');

  const header = normalized.slice(4, closing);
  const body = normalized.slice(closing + 5).trim();
  const attributes = {};
  let listKey;

  for (const rawLine of header.split('\n')) {
    const listMatch = rawLine.match(/^\s+-\s+["']?(.+?)["']?\s*$/);
    if (listMatch && listKey) {
      attributes[listKey].push(listMatch[1]);
      continue;
    }

    const fieldMatch = rawLine.match(/^([A-Za-z0-9_-]+):\s*(.*?)\s*$/);
    if (!fieldMatch) continue;
    const [, key, rawValue] = fieldMatch;
    if (!rawValue) {
      attributes[key] = [];
      listKey = key;
    } else {
      attributes[key] = rawValue.replace(/^["']|["']$/g, '');
      listKey = undefined;
    }
  }

  return { attributes, body };
}

function toSafeName(value) {
  const name = value
    .toLowerCase()
    .replace(/[^a-z0-9_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  if (!name) throw new Error(`Không thể tạo tên an toàn từ: ${value}`);
  return name;
}

async function buildExpectedOutputs() {
  const expected = new Map();
  for (const output of managedOutputs) expected.set(path.join(output, markerName), markerContent);

  const skillSource = path.join(root, '.claude', 'skills');
  for (const sourceFile of await walkFiles(skillSource)) {
    const destination = path.join(
      root,
      '.agents',
      'skills',
      path.relative(skillSource, sourceFile),
    );
    expected.set(destination, await readFile(sourceFile, 'utf8'));
  }

  const commandsSource = path.join(root, '.claude', 'commands');
  for (const sourceFile of await walkFiles(commandsSource)) {
    if (path.extname(sourceFile) !== '.md') continue;
    const source = await readFile(sourceFile, 'utf8');
    const { attributes, body } = parseFrontmatter(source);
    const commandName = toSafeName(
      path.relative(commandsSource, sourceFile).replace(/\.md$/i, '').replaceAll(path.sep, '-'),
    );
    const description = attributes.description || `Thực thi quy trình ${commandName}.`;
    const destination = path.join(root, '.agents', 'skills', commandName, 'SKILL.md');
    if (expected.has(destination)) throw new Error(`Trùng skill đầu ra: ${relative(destination)}`);
    expected.set(
      destination,
      `---\nname: ${commandName}\ndescription: ${description}\n---\n\n${body}\n`,
    );
  }

  const rulesSource = path.join(root, '.claude', 'rules');
  for (const sourceFile of await walkFiles(rulesSource)) {
    if (path.extname(sourceFile) !== '.md') continue;
    const source = await readFile(sourceFile, 'utf8');
    const { attributes, body } = parseFrontmatter(source);
    const ruleName = toSafeName(
      path.relative(rulesSource, sourceFile).replace(/\.md$/i, '').replaceAll(path.sep, '-'),
    );
    const paths = Array.isArray(attributes.paths) ? attributes.paths : [];
    const frontmatter = paths.length
      ? `trigger: glob\nglobs: ${JSON.stringify(paths.join(', '))}\ndescription: ${JSON.stringify(`Áp dụng quy tắc ${ruleName} cho các file phù hợp.`)}`
      : 'trigger: always_on';
    const destination = path.join(root, '.agents', 'rules', `${ruleName}.md`);
    expected.set(destination, `---\n${frontmatter}\n---\n\n${body}\n`);
  }

  const agentsSource = path.join(root, '.claude', 'agents');
  for (const sourceFile of await walkFiles(agentsSource)) {
    if (path.extname(sourceFile) !== '.md') continue;
    const source = await readFile(sourceFile, 'utf8');
    const { attributes, body } = parseFrontmatter(source);
    const fallbackName = path.basename(sourceFile, '.md');
    const agentName = toSafeName(attributes.name || fallbackName);
    const description = attributes.description;
    if (!description)
      throw new Error(`${relative(sourceFile)} thiếu description trong frontmatter`);
    const destination = path.join(root, '.codex', 'agents', `${agentName}.toml`);
    expected.set(
      destination,
      `name = ${JSON.stringify(agentName)}\ndescription = ${JSON.stringify(description)}\ndeveloper_instructions = ${JSON.stringify(body)}\n`,
    );
  }

  return expected;
}

async function assertManagedDirectory(directory) {
  if (!(await exists(directory))) return;
  if ((await readdir(directory)).length === 0) return;
  if (!(await exists(path.join(directory, markerName)))) {
    throw new Error(
      `Từ chối ghi đè thư mục chưa được đánh dấu là đầu ra tự động: ${relative(directory)}`,
    );
  }
}

async function compare(expected) {
  const differences = [];
  for (const directory of managedOutputs) {
    const actualFiles = await walkFiles(directory);
    const expectedFiles = [...expected.keys()].filter((file) =>
      path.dirname(file).startsWith(directory),
    );
    const allFiles = new Set([...actualFiles, ...expectedFiles]);

    for (const file of allFiles) {
      if (!expected.has(file)) {
        differences.push(`${relative(file)}: file thừa`);
        continue;
      }
      if (!(await exists(file))) {
        differences.push(`${relative(file)}: file còn thiếu`);
        continue;
      }
      if ((await readFile(file, 'utf8')) !== expected.get(file)) {
        differences.push(`${relative(file)}: nội dung chưa đồng bộ`);
      }
    }
  }
  return differences;
}

async function synchronize(expected) {
  for (const directory of managedOutputs) {
    await assertManagedDirectory(directory);
    await rm(directory, { recursive: true, force: true });
  }

  for (const [destination, content] of expected) {
    await mkdir(path.dirname(destination), { recursive: true });
    await writeFile(destination, content, 'utf8');
  }
}

const expected = await buildExpectedOutputs();

if (checkOnly) {
  const differences = await compare(expected);
  if (differences.length) {
    console.error('Cấu hình AI chưa đồng bộ:');
    for (const difference of differences) console.error(`- ${difference}`);
    console.error('Chạy npm run ai:sync để cập nhật.');
    process.exitCode = 1;
  } else {
    console.log('Cấu hình AI đã đồng bộ.');
  }
} else {
  await synchronize(expected);
  console.log(`Đã đồng bộ ${expected.size - managedOutputs.length} file cấu hình AI.`);
}
